import React from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';

const priorityColors = { High: '#ffdddd', Medium: '#fff3cd', Low: '#e6ffed' };

export default function TaskCard({ task, onEdit, onDelete, onToggleStatus }) {
  return (
    <div className="task-card" style={{ background: priorityColors[task.priority] }}>
      <Link to={`/tasks/${task._id}`} className="task-title">
        {task.title}
      </Link>
      <div className="meta">
        <small>Due: {task.dueDate ? format(new Date(task.dueDate), 'PP') : '—'}</small>
        <small>Status: {task.status}</small>
      </div>
      <div className="task-actions">
        <button onClick={() => onToggleStatus(task)}>{task.status === 'Pending' ? 'Complete' : 'Reopen'}</button>
        <button onClick={() => onEdit(task)}>Edit</button>
        <button className="danger" onClick={() => onDelete(task)}>Delete</button>
      </div>
    </div>
  );
}
